  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy astrophysical neutrinos as a new observational window on the Universe, a major experimental achievement with lasting value for astroparticle physics.",
        "attribution": "Halzen was central to the detector's scientific conception and leadership; Karle and Spiering represent crucial detector and early project contributions. Credit across a large international collaboration is difficult to compress into three names.",
        "maturity": "The detection is established and subsequent observations have strengthened the field, though identifying individual cosmic sources remains an active task.",
        "uncertainties": [
          "The extent to which the initial discovery and later source identifications should be treated as one prizeworthy contribution is debatable."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Fabiola Gianotti",
        "Peter Jenni",
        "Tejinder S. Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson confirmed a central prediction of the Standard Model and was a landmark in particle physics.",
        "attribution": "These names represent major leadership of ATLAS and CMS and the long work of realizing the detectors and discovery. The result depended on thousands of contributors, making any small selection incomplete.",
        "maturity": "The discovery has been repeatedly confirmed, and measured properties continue to fit the Higgs mechanism.",
        "uncertainties": [
          "The division of credit among experiment leaders, detector builders, and the wider collaborations is necessarily selective."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B052",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of cosmic microwave background anisotropies transformed cosmology into a precision science and constrained the contents and history of the Universe.",
        "attribution": "Bennett and Page represent the mission's experimental and instrumental leadership, while Spergel made a major contribution to interpreting its cosmological results. The achievement was broadly collaborative.",
        "maturity": "The measurements and their cosmological implications have been extensively checked and developed by later observations.",
        "uncertainties": [
          "Some of the strongest precision claims rely on a cosmological model and later missions share credit for the broader result."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks opened a route to exceptionally precise timekeeping and tests of fundamental physics, with important prospects for sensing and metrology.",
        "attribution": "Katori and Ye made complementary foundational contributions to the lattice-clock approach and its experimental realization.",
        "maturity": "The technique is well established, with clocks now reaching extraordinary precision and independent groups reproducing and extending the work.",
        "uncertainties": [
          "The prize case depends on judging the clock's scientific reach and lasting impact, not precision alone."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "The Event Horizon Telescope produced the first horizon-scale images of black holes, a striking confirmation of strong-gravity predictions and a new observational capability.",
        "attribution": "Falcke helped establish the scientific vision, Zensus contributed major leadership in very long baseline interferometry, and Doeleman led the observing effort. The image depended on a large global collaboration.",
        "maturity": "The results have been checked and extended with further imaging and observations, though interpretation continues to improve.",
        "uncertainties": [
          "It remains difficult to separate the contributions of the named leaders from the many teams that made the array and analysis possible."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B010",
      "proposed_laureates": [
        "James L. Burch",
        "Roy B. Torbert",
        "Tai D. Phan"
      ],
      "assessment": {
        "nobel_worthiness": "MMS measurements resolved magnetic reconnection at electron scales in space plasmas, turning a central plasma-physics process into a directly observed phenomenon.",
        "attribution": "Burch led the mission, Torbert led key instrument work, and Phan contributed substantially to reconnection research and interpretation. The measurement depends on a broad spacecraft and science team.",
        "maturity": "The mission has yielded extensive observations, but the wider implications for reconnection across different plasma environments remain under study.",
        "uncertainties": [
          "The case may be viewed as a major mission result within a continuing research program rather than a single, finished discovery."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "John A. Peacock",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery and use of baryon acoustic oscillations as a cosmic standard ruler gave cosmology a powerful way to measure cosmic expansion and test dark energy.",
        "attribution": "Eisenstein, Cole, and Peacock were central to the early survey work and establishment of the method, though later surveys and many groups built on it.",
        "maturity": "The standard-ruler measurement is now a robust part of observational cosmology, supported by independent surveys.",
        "uncertainties": [
          "The contribution is distributed across theory, survey teams, and subsequent measurements, complicating a narrow attribution."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the standard quantum limit and has become an important tool for precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves supplied foundational theory, Kimble advanced experimental quantum optics, and Mavalvala helped establish its use in precision interferometry. This selection cannot represent all the experimental teams involved.",
        "maturity": "The technique is demonstrated and deployed in major instruments, with continued improvements in sensitivity.",
        "uncertainties": [
          "The award-worthy contribution may be difficult to delimit because squeezed light developed through a long sequence of theoretical and experimental work."
        ]
      }
    }
  ]
}
